class HealthRecordServicer(ehr_pb2_grpc.EHRServiceServicer):
    async def StreamHealthSummary(self, request, context):
        doctor = await authenticate_doctor_metadata(context)
        async with AsyncSessionLocal() as session:
            assignment = await session.execute(
                select(CareTeam).filter(
                    CareTeam.doctor_id == doctor.id,
                    CareTeam.patient_mrn == request.patient_mrn
                )
            )
            if not assignment.scalars().first():
                await context.abort(grpc.StatusCode.PERMISSION_DENIED, "Doctor not assigned to patient care team")
            result = await session.execute(
                select(MedicalRecord).filter(MedicalRecord.patient_mrn == request.patient_mrn)
            )
            records = result.scalars().all()
            for r in records:
                yield ehr_pb2.RecordChunk(diagnosis=r.diagnosis, medication=r.prescriptions)
